/**
 * Definition for a binary tree node.
 * struct TreeNode {
 *     int val;
 *     TreeNode *left;
 *     TreeNode *right;
 *     TreeNode(int x) : val(x), left(NULL), right(NULL) {}
 * };
 */
class Solution {
public:
    TreeNode* mergeTrees(TreeNode* t1, TreeNode* t2) {
        if(NULL == t1)
            return t2;
        if(NULL == t2)
            return t1;
        TreeNode* res = t1;
        stack<TreeNode*> s1,s2;
        s1.push(t1);
        s2.push(t2);

        while(!s1.empty())
        {
            TreeNode* p1 = s1.top();
            TreeNode* p2 = s2.top();
            s1.pop();
            s2.pop();
            p1->val += p2->val;
            if(p1->right == NULL && p2->right != NULL) p1->right = p2->right;
            else if(p1->right != NULL && p2->right != NULL) s1.push(p1->right),s2.push(p2->right);

            if(p1->left == NULL && p2->left != NULL) p1->left = p2->left;
            else if(p1->left != NULL && p2->left != NULL) s1.push(p1->left), s2.push(p2->left);

        }
        return res;
    }
};

